package com.radix.app

/** Human-readable titles and explanations from the logic-model catalog. */
internal object LogicCatalogTranslations {
    private data class Text3(val fr:String,val es:String,val pt:String)
    private val entries=mapOf(
        "All inputs must be 1." to Text3("Toutes les entrées doivent valoir 1.","Todas las entradas deben ser 1.","Todas as entradas precisam ser 1."),
        "An AND gate only outputs 1 when every input is 1." to Text3("Une porte AND ne produit 1 que si toutes ses entrées valent 1.","Una puerta AND solo da 1 cuando todas sus entradas valen 1.","Uma porta AND só produz 1 quando todas as entradas são 1."),
        "At least one input is 1." to Text3("Au moins une entrée vaut 1.","Al menos una entrada vale 1.","Pelo menos uma entrada vale 1."),
        "OR is inclusive: both inputs at 1 still produce 1." to Text3("OR est inclusif : deux entrées à 1 produisent aussi 1.","OR es inclusivo: dos entradas en 1 también dan 1.","OR é inclusivo: duas entradas em 1 também produzem 1."),
        "Reverse one input." to Text3("Inversez une entrée.","Invierte una entrada.","Inverta uma entrada."),
        "The small output bubble means inversion. NOT has exactly one input." to Text3("La petite bulle en sortie indique une inversion. NOT a exactement une entrée.","La pequeña burbuja de salida indica inversión. NOT tiene exactamente una entrada.","A pequena bolha na saída indica inversão. NOT tem exatamente uma entrada."),
        "Invert the AND result." to Text3("Inversez le résultat de AND.","Invierte el resultado de AND.","Inverta o resultado de AND."),
        "NAND is universal: combinations of NAND gates can implement any Boolean function." to Text3("NAND est universelle : des combinaisons de portes NAND peuvent réaliser toute fonction booléenne.","NAND es universal: combinaciones de puertas NAND pueden implementar cualquier función booleana.","NAND é universal: combinações de portas NAND implementam qualquer função booleana."),
        "Invert the OR result." to Text3("Inversez le résultat de OR.","Invierte el resultado de OR.","Inverta o resultado de OR."),
        "NOR is universal. Its output is 1 only when all inputs are 0." to Text3("NOR est universelle. Sa sortie vaut 1 uniquement si toutes les entrées valent 0.","NOR es universal. Su salida es 1 solo cuando todas las entradas son 0.","NOR é universal. Sua saída é 1 somente quando todas as entradas são 0."),
        "An odd number of inputs is 1." to Text3("Un nombre impair d’entrées vaut 1.","Un número impar de entradas vale 1.","Um número ímpar de entradas vale 1."),
        "For two inputs XOR means different. With 3 or 4 inputs, it means ODD parity—not exactly one 1." to Text3("Avec deux entrées, XOR signifie différent. Avec 3 ou 4 entrées, il indique une parité IMPAIRE, pas exactement un seul 1.","Con dos entradas, XOR significa distinto. Con 3 o 4, indica paridad IMPAR, no exactamente un solo 1.","Com duas entradas, XOR significa diferente. Com 3 ou 4, indica paridade ÍMPAR — não exatamente um único 1."),
        "An even number of inputs is 1." to Text3("Un nombre pair d’entrées vaut 1.","Un número par de entradas vale 1.","Um número par de entradas vale 1."),
        "For two inputs XNOR means equal. With 3 or 4 inputs, it means EVEN parity—not that all inputs are equal." to Text3("Avec deux entrées, XNOR signifie égal. Avec 3 ou 4 entrées, il indique une parité PAIRE, pas que toutes les entrées sont égales.","Con dos entradas, XNOR significa igual. Con 3 o 4, indica paridad PAR, no que todas sean iguales.","Com duas entradas, XNOR significa igual. Com 3 ou 4, indica paridade PAR — não que todas sejam iguais."),
        "Keep the input unchanged." to Text3("Conservez l’entrée inchangée.","Mantén la entrada sin cambios.","Mantenha a entrada inalterada."),
        "A buffer has one input. It preserves the logic value; electrical drive strength is not modeled." to Text3("Un BUFFER a une entrée. Il conserve la valeur logique ; la capacité électrique de commande n’est pas modélisée.","Un BUFFER tiene una entrada. Conserva el valor lógico; no se modela la capacidad eléctrica de salida.","Um BUFFER tem uma entrada. Preserva o valor lógico; a capacidade elétrica de acionamento não é modelada."),
        "Sum = A ⊕ B" to Text3("Somme = A ⊕ B","Suma = A ⊕ B","Soma = A ⊕ B"),
        "Carry = A · B" to Text3("Retenue = A · B","Acarreo = A · B","Transporte = A · B"),
        "Sum = A ⊕ B ⊕ Cin" to Text3("Somme = A ⊕ B ⊕ Cin","Suma = A ⊕ B ⊕ Cin","Soma = A ⊕ B ⊕ Cin"),
        "Diff = A ⊕ B" to Text3("Différence = A ⊕ B","Diferencia = A ⊕ B","Diferença = A ⊕ B"),
        "Borrow = A′B" to Text3("Emprunt = A′B","Préstamo = A′B","Empréstimo = A′B"),
        "Diff = A ⊕ B ⊕ Bin" to Text3("Différence = A ⊕ B ⊕ Bin","Diferencia = A ⊕ B ⊕ Bin","Diferença = A ⊕ B ⊕ Bin"),
        "EN=0: all outputs 0" to Text3("EN=0 : toutes les sorties valent 0","EN=0: todas las salidas valen 0","EN=0: todas as saídas são 0"),
        "Y1Y0 = highest asserted input index" to Text3("Y1Y0 = indice le plus élevé parmi les entrées actives","Y1Y0 = índice más alto entre las entradas activas","Y1Y0 = índice mais alto entre as entradas ativas"),
        "Compare A1 vs B1 first" to Text3("Comparez d’abord A1 et B1","Compara primero A1 con B1","Compare A1 com B1 primeiro"),
        "If equal, compare A0 vs B0" to Text3("S’ils sont égaux, comparez A0 et B0","Si son iguales, compara A0 con B0","Se forem iguais, compare A0 com B0"),
        "Y = D[base-2 index selected by S2, S1, S0]" to Text3("Y = D[indice en base 2 sélectionné par S2, S1, S0]","Y = D[índice en base 2 seleccionado por S2, S1, S0]","Y = D[índice na base 2 selecionado por S2, S1, S0]"),
        "Y = D[base-2 index selected by S3, S2, S1, S0]" to Text3("Y = D[indice en base 2 sélectionné par S3, S2, S1, S0]","Y = D[índice en base 2 seleccionado por S3, S2, S1, S0]","Y = D[índice na base 2 selecionado por S3, S2, S1, S0]"),
        "Y0 = D · minterm(S) for select 00" to Text3("Y0 = D · minterme(S) pour la sélection 00","Y0 = D · mintermino(S) para la selección 00","Y0 = D · mintermo(S) para a seleção 00"),
        "Y1 = D · minterm(S) for select 01" to Text3("Y1 = D · minterme(S) pour la sélection 01","Y1 = D · mintermino(S) para la selección 01","Y1 = D · mintermo(S) para a seleção 01"),
        "Y2 = D · minterm(S) for select 10" to Text3("Y2 = D · minterme(S) pour la sélection 10","Y2 = D · mintermino(S) para la selección 10","Y2 = D · mintermo(S) para a seleção 10"),
        "Y3 = D · minterm(S) for select 11" to Text3("Y3 = D · minterme(S) pour la sélection 11","Y3 = D · mintermino(S) para la selección 11","Y3 = D · mintermo(S) para a seleção 11"),
        "Y[i] = D when select = i; all other outputs are 0." to Text3("Y[i] = D quand la sélection vaut i ; toutes les autres sorties valent 0.","Y[i] = D cuando la selección vale i; todas las demás salidas valen 0.","Y[i] = D quando a seleção vale i; todas as outras saídas são 0."),
        "Y[i] = 1 exactly when input A = i (0…7)." to Text3("Y[i] = 1 exactement quand l’entrée A vaut i (0…7).","Y[i] = 1 exactamente cuando la entrada A vale i (0…7).","Y[i] = 1 exatamente quando a entrada A vale i (0…7)."),
        "Y[i] = 1 exactly when input A = i (0…15)." to Text3("Y[i] = 1 exactement quand l’entrée A vaut i (0…15).","Y[i] = 1 exactamente cuando la entrada A vale i (0…15).","Y[i] = 1 exatamente quando a entrada A vale i (0…15)."),
        "LT is true at the first (most-significant) bit where A=0 and B=1." to Text3("LT vaut 1 au premier bit (de poids fort) où A=0 et B=1.","LT es 1 en el primer bit (más significativo) donde A=0 y B=1.","LT vale 1 no primeiro bit (mais significativo) em que A=0 e B=1."),
        "Exactly one of LT, EQ or GT is 1." to Text3("Une seule de LT, EQ ou GT vaut 1.","Exactamente una de LT, EQ o GT vale 1.","Exatamente uma entre LT, EQ e GT vale 1."),
        "Even = (A ⊕ B ⊕ C ⊕ P)′" to Text3("Pair = (A ⊕ B ⊕ C ⊕ P)′","Par = (A ⊕ B ⊕ C ⊕ P)′","Par = (A ⊕ B ⊕ C ⊕ P)′"),
        "Error = A ⊕ B ⊕ C ⊕ P" to Text3("Erreur = A ⊕ B ⊕ C ⊕ P","Error = A ⊕ B ⊕ C ⊕ P","Erro = A ⊕ B ⊕ C ⊕ P"),
        "A B C D are 8-4-2-1 BCD inputs." to Text3("A, B, C et D sont les entrées BCD de poids 8-4-2-1.","A, B, C y D son las entradas BCD con pesos 8-4-2-1.","A, B, C e D são as entradas BCD com pesos 8-4-2-1."),
        "a…g are active-high segments for a common-cathode display." to Text3("a…g sont les segments actifs à 1 d’un afficheur à cathode commune.","a…g son los segmentos activos en alto de una pantalla de cátodo común.","a…g são os segmentos ativos em nível alto de um display de cátodo comum."),
        "Half adder" to Text3("Demi-additionneur","Semisumador","Meio somador"),
        "Adds two one-bit values. It has no carry-in." to Text3("Additionne deux valeurs d’un bit. Il n’a pas de retenue d’entrée.","Suma dos valores de un bit. No tiene acarreo de entrada.","Soma dois valores de um bit. Não possui carry de entrada."),
        "Read Carry:Sum as a two-bit number; 1 + 1 = 10₂, not a single output of 2." to Text3("Lisez Retenue:Somme comme un nombre de deux bits : 1 + 1 = 10₂, pas une sortie unique égale à 2.","Lee Acarreo:Suma como un número de dos bits: 1 + 1 = 10₂, no como una salida única de 2.","Leia Transporte:Soma como um número de dois bits: 1 + 1 = 10₂, não como uma saída única de 2."),
        "Full adder" to Text3("Additionneur complet","Sumador completo","Somador completo"),
        "Includes a carry-in, so three one-bit values are added." to Text3("Inclut une retenue d’entrée : trois valeurs d’un bit sont donc additionnées.","Incluye acarreo de entrada, así que se suman tres valores de un bit.","Inclui carry de entrada, então três valores de um bit são somados."),
        "Cout:Sum represents A + B + Cin. Connect Cout to the next stage’s Cin for a ripple adder." to Text3("Cout:Somme représente A + B + Cin. Reliez Cout au Cin de l’étage suivant pour former un additionneur à propagation.","Cout:Suma representa A + B + Cin. Conecta Cout al Cin de la etapa siguiente para formar un sumador en cascada.","Cout:Soma representa A + B + Cin. Conecte Cout ao Cin do próximo estágio para formar um somador em cascata."),
        "Half subtractor" to Text3("Demi-soustracteur","Semirrestador","Meio subtrator"),
        "Subtracts B from A. Operand order matters." to Text3("Soustrait B de A. L’ordre des opérandes est important.","Resta B de A. El orden de los operandos importa.","Subtrai B de A. A ordem dos operandos importa."),
        "When A=0 and B=1, Diff=1 with Borrow=1. This is binary subtraction, not an ordinary negative output bit." to Text3("Quand A=0 et B=1, Différence=1 et Emprunt=1. C’est une soustraction binaire, pas un bit de sortie négatif ordinaire.","Cuando A=0 y B=1, Diferencia=1 y Préstamo=1. Es una resta binaria, no un bit de salida negativo común.","Quando A=0 e B=1, Diferença=1 e Empréstimo=1. É subtração binária, não um bit de saída negativo comum."),
        "Full subtractor" to Text3("Soustracteur complet","Restador completo","Subtrator completo"),
        "Computes A − B − Bin." to Text3("Calcule A − B − Bin.","Calcula A − B − Bin.","Calcula A − B − Bin."),
        "Bout indicates that the next higher stage must supply a borrow; Diff = (A − B − Bin) mod 2." to Text3("Bout indique que l’étage de poids supérieur doit fournir un emprunt ; Différence = (A − B − Bin) mod 2.","Bout indica que la etapa superior debe aportar un préstamo; Diferencia = (A − B − Bin) mod 2.","Bout indica que o próximo estágio mais significativo deve fornecer um empréstimo; Diferença = (A − B − Bin) mod 2."),
        "2:1 multiplexer" to Text3("Multiplexeur 2:1","Multiplexor 2:1","Multiplexador 2:1"),
        "A multiplexer selects one data input, not one output." to Text3("Un multiplexeur sélectionne une entrée de données, pas une sortie.","Un multiplexor selecciona una entrada de datos, no una salida.","Um multiplexador seleciona uma entrada de dados, não uma saída."),
        "S=0 selects D0; S=1 selects D1. Changing an unselected input does not affect Y." to Text3("S=0 sélectionne D0 ; S=1 sélectionne D1. Modifier une entrée non sélectionnée ne change pas Y.","S=0 selecciona D0; S=1 selecciona D1. Cambiar una entrada no seleccionada no afecta a Y.","S=0 seleciona D0; S=1 seleciona D1. Alterar uma entrada não selecionada não afeta Y."),
        "4:1 multiplexer" to Text3("Multiplexeur 4:1","Multiplexor 4:1","Multiplexador 4:1"),
        "S1 is the most significant select bit. 00/01/10/11 select D0/D1/D2/D3." to Text3("S1 est le bit de sélection le plus significatif. 00/01/10/11 sélectionnent D0/D1/D2/D3.","S1 es el bit de selección más significativo. 00/01/10/11 seleccionan D0/D1/D2/D3.","S1 é o bit de seleção mais significativo. 00/01/10/11 selecionam D0/D1/D2/D3."),
        "There are six independent inputs, so the full truth table has 64 rows." to Text3("Il y a six entrées indépendantes ; la table de vérité complète comporte donc 64 lignes.","Hay seis entradas independientes, así que la tabla de verdad completa tiene 64 filas.","Há seis entradas independentes, então a tabela-verdade completa tem 64 linhas."),
        "1:2 demultiplexer" to Text3("Démultiplexeur 1:2","Demultiplexor 1:2","Demultiplexador 1:2"),
        "Routes one data input to one selected output." to Text3("Achemine une entrée de données vers la sortie sélectionnée.","Envía una entrada de datos a la salida seleccionada.","Encaminha uma entrada de dados à saída selecionada."),
        "The unselected output is 0. It is not a multiplexer with reversed labels." to Text3("La sortie non sélectionnée vaut 0. Ce n’est pas un multiplexeur aux libellés inversés.","La salida no seleccionada es 0. No es un multiplexor con las etiquetas invertidas.","A saída não selecionada é 0. Não é um multiplexador com os rótulos invertidos."),
        "2:4 decoder + enable" to Text3("Décodeur 2:4 avec validation","Decodificador 2:4 con habilitación","Decodificador 2:4 com habilitação"),
        "Active-high one-hot outputs. A is the MSB." to Text3("Sorties one-hot actives à 1. A est le MSB.","Salidas one-hot activas en alto. A es el MSB.","Saídas one-hot ativas em nível alto. A é o MSB."),
        "When disabled no output is asserted; this differs from a decoder without an enable input." to Text3("Désactivé, aucune sortie n’est activée ; c’est différent d’un décodeur sans entrée de validation.","Deshabilitado, ninguna salida se activa; esto difiere de un decodificador sin entrada de habilitación.","Desabilitado, nenhuma saída é ativada; isso difere de um decodificador sem entrada de habilitação."),
        "4:2 priority encoder" to Text3("Codeur prioritaire 4:2","Codificador de prioridad 4:2","Codificador de prioridade 4:2"),
        "Unlike a basic one-hot encoder, multiple active inputs are allowed: the highest index wins." to Text3("Contrairement à un codeur one-hot simple, plusieurs entrées peuvent être actives : l’indice le plus élevé est prioritaire.","A diferencia de un codificador one-hot básico, se permiten varias entradas activas: gana el índice más alto.","Diferente de um codificador one-hot básico, várias entradas podem estar ativas: vence o maior índice."),
        "Valid distinguishes D0=1 (code 00) from no active input (code 00, Valid=0)." to Text3("Valide distingue D0=1 (code 00) de l’absence d’entrée active (code 00, Valide=0).","Válida distingue D0=1 (código 00) de ninguna entrada activa (código 00, Válida=0).","Válida distingue D0=1 (código 00) de nenhuma entrada ativa (código 00, Válida=0)."),
        "1-bit magnitude comparator" to Text3("Comparateur de magnitude 1 bit","Comparador de magnitud de 1 bit","Comparador de magnitude de 1 bit"),
        "Compares unsigned one-bit values." to Text3("Compare des valeurs non signées sur un bit.","Compara valores sin signo de un bit.","Compara valores sem sinal de um bit."),
        "Exactly one of LT/EQ/GT is 1 for every valid input." to Text3("Pour chaque entrée valide, une seule sortie parmi LT/EQ/GT vaut 1.","Para cada entrada válida, exactamente una salida entre LT/EQ/GT vale 1.","Para cada entrada válida, exatamente uma das saídas LT/EQ/GT vale 1."),
        "2-bit magnitude comparator" to Text3("Comparateur de magnitude 2 bits","Comparador de magnitud de 2 bits","Comparador de magnitude de 2 bits"),
        "Unsigned values A=2A1+A0 and B=2B1+B0." to Text3("Valeurs non signées A=2A1+A0 et B=2B1+B0.","Valores sin signo A=2A1+A0 y B=2B1+B0.","Valores sem sinal A=2A1+A0 e B=2B1+B0."),
        "The least-significant comparison only matters when the most-significant bits match." to Text3("La comparaison des bits de poids faible ne compte que si les bits de poids fort sont égaux.","La comparación del bit menos significativo solo importa si coinciden los más significativos.","A comparação do bit menos significativo só importa quando os bits mais significativos são iguais."),
        "4-bit ripple-carry adder" to Text3("Additionneur à propagation 4 bits","Sumador en cascada de 4 bits","Somador em cascata de 4 bits"),
        "Four full-adder stages carry from bit 0 toward bit 3." to Text3("Quatre étages d’additionneur complet propagent la retenue du bit 0 au bit 3.","Cuatro etapas de sumador completo propagan el acarreo del bit 0 al bit 3.","Quatro estágios de somador completo propagam o carry do bit 0 ao bit 3."),
        "A3/B3 are the MSBs. S3…S0 is the low four-bit sum; Cout is the fifth bit." to Text3("A3/B3 sont les MSB. S3…S0 est la somme sur les quatre bits faibles ; Cout est le cinquième bit.","A3/B3 son los MSB. S3…S0 es la suma de los cuatro bits bajos; Cout es el quinto bit.","A3/B3 são os MSBs. S3…S0 é a soma dos quatro bits menos significativos; Cout é o quinto bit."),
        "This ideal model has no propagation-delay simulation. The 512-row truth table is paginated." to Text3("Ce modèle idéal ne simule pas les délais de propagation. La table de vérité de 512 lignes est paginée.","Este modelo ideal no simula retardos de propagación. La tabla de 512 filas se muestra por páginas.","Este modelo ideal não simula atrasos de propagação. A tabela-verdade de 512 linhas é paginada."),
        "8:1 multiplexer" to Text3("Multiplexeur 8:1","Multiplexor 8:1","Multiplexador 8:1"),
        "3 select bits choose exactly one of 8 data inputs." to Text3("3 bits de sélection choisissent exactement une entrée parmi 8.","3 bits de selección eligen exactamente una de las 8 entradas de datos.","3 bits de seleção escolhem exatamente uma das 8 entradas de dados."),
        "Select inputs are ordered most-significant first; 0… selects D0…D7." to Text3("Les sélections sont ordonnées du bit de poids fort au plus faible ; 0… sélectionne D0…D7.","Las selecciones se ordenan del bit más significativo al menos significativo; 0… selecciona D0…D7.","As seleções são ordenadas do bit mais significativo ao menos significativo; 0… seleciona D0…D7."),
        "A full table has 2^11 rows and is paginated on demand." to Text3("La table complète comporte 2^11 lignes, affichées par pages à la demande.","La tabla completa tiene 2^11 filas y se pagina bajo demanda.","A tabela completa tem 2^11 linhas e é paginada sob demanda."),
        "16:1 multiplexer" to Text3("Multiplexeur 16:1","Multiplexor 16:1","Multiplexador 16:1"),
        "4 select bits choose exactly one of 16 data inputs." to Text3("4 bits de sélection choisissent exactement une entrée parmi 16.","4 bits de selección eligen exactamente una de las 16 entradas de datos.","4 bits de seleção escolhem exatamente uma das 16 entradas de dados."),
        "Select inputs are ordered most-significant first; 0… selects D0…D15." to Text3("Les sélections sont ordonnées du bit de poids fort au plus faible ; 0… sélectionne D0…D15.","Las selecciones se ordenan del bit más significativo al menos significativo; 0… selecciona D0…D15.","As seleções são ordenadas do bit mais significativo ao menos significativo; 0… seleciona D0…D15."),
        "A full table has 2^20 rows and is paginated on demand." to Text3("La table complète comporte 2^20 lignes, affichées par pages à la demande.","La tabla completa tiene 2^20 filas y se pagina bajo demanda.","A tabela completa tem 2^20 linhas e é paginada sob demanda."),
        "1:4 demultiplexer" to Text3("Démultiplexeur 1:4","Demultiplexor 1:4","Demultiplexador 1:4"),
        "Routes one data input to the output selected by the binary select word." to Text3("Achemine l’entrée de données vers la sortie choisie par le mot de sélection binaire.","Envía la entrada de datos a la salida seleccionada por la palabra binaria de selección.","Encaminha a entrada de dados à saída selecionada pela palavra binária de seleção."),
        "Select inputs are most-significant first. With D=0 every output is 0." to Text3("Les sélections sont présentées du bit de poids fort au plus faible. Avec D=0, toutes les sorties valent 0.","Las entradas de selección van del bit más significativo al menos significativo. Con D=0, todas las salidas son 0.","As entradas de seleção vão do bit mais significativo ao menos significativo. Com D=0, todas as saídas são 0."),
        "A full table has 2^3 rows and is paginated on demand." to Text3("La table complète comporte 2^3 lignes, affichées par pages à la demande.","La tabla completa tiene 2^3 filas y se pagina bajo demanda.","A tabela completa tem 2^3 linhas e é paginada sob demanda."),
        "1:8 demultiplexer" to Text3("Démultiplexeur 1:8","Demultiplexor 1:8","Demultiplexador 1:8"),
        "A full table has 2^4 rows and is paginated on demand." to Text3("La table complète comporte 2^4 lignes, affichées par pages à la demande.","La tabla completa tiene 2^4 filas y se pagina bajo demanda.","A tabela completa tem 2^4 linhas e é paginada sob demanda."),
        "1:16 demultiplexer" to Text3("Démultiplexeur 1:16","Demultiplexor 1:16","Demultiplexador 1:16"),
        "A full table has 2^5 rows and is paginated on demand." to Text3("La table complète comporte 2^5 lignes, affichées par pages à la demande.","La tabla completa tiene 2^5 filas y se pagina bajo demanda.","A tabela completa tem 2^5 linhas e é paginada sob demanda."),
        "3:8 decoder" to Text3("Décodeur 3:8","Decodificador 3:8","Decodificador 3:8"),
        "Active-high one-hot outputs; exactly one output is 1 for every input word." to Text3("Sorties one-hot actives à 1 ; une seule sortie vaut 1 pour chaque mot d’entrée.","Salidas one-hot activas en alto; exactamente una salida vale 1 para cada palabra de entrada.","Saídas one-hot ativas em nível alto; exatamente uma saída vale 1 para cada palavra de entrada."),
        "Input A2 is the most significant bit." to Text3("L’entrée A2 est le bit de poids fort.","La entrada A2 es el bit más significativo.","A entrada A2 é o bit mais significativo."),
        "4:16 decoder" to Text3("Décodeur 4:16","Decodificador 4:16","Decodificador 4:16"),
        "Input A3 is the most significant bit." to Text3("L’entrée A3 est le bit de poids fort.","La entrada A3 es el bit más significativo.","A entrada A3 é o bit mais significativo."),
        "4-bit magnitude comparator" to Text3("Comparateur de magnitude 4 bits","Comparador de magnitud de 4 bits","Comparador de magnitude de 4 bits"),
        "Unsigned words A=A3A2A1A0 and B=B3B2B1B0 are compared lexicographically from the MSB." to Text3("Les mots non signés A=A3A2A1A0 et B=B3B2B1B0 sont comparés lexicographiquement à partir du MSB.","Las palabras sin signo A=A3A2A1A0 y B=B3B2B1B0 se comparan desde el MSB.","As palavras sem sinal A=A3A2A1A0 e B=B3B2B1B0 são comparadas a partir do MSB."),
        "A lower bit matters only when every more-significant bit is equal." to Text3("Un bit de poids inférieur ne compte que si tous les bits de poids supérieur sont égaux.","Un bit inferior solo importa cuando todos los de mayor peso son iguales.","Um bit menos significativo só importa quando todos os mais significativos são iguais."),
        "3-bit even-parity generator" to Text3("Générateur de parité paire 3 bits","Generador de paridad par de 3 bits","Gerador de paridade par de 3 bits"),
        "Append P to the three data bits." to Text3("Ajoutez P aux trois bits de données.","Añade P a los tres bits de datos.","Acrescente P aos três bits de dados."),
        "P is 1 when the data contain an odd number of 1s, making the total number of 1s even." to Text3("P vaut 1 lorsque les données contiennent un nombre impair de 1, afin que le total soit pair.","P vale 1 cuando los datos tienen un número impar de 1, para que el total sea par.","P vale 1 quando os dados contêm uma quantidade ímpar de 1, tornando o total par."),
        "4-bit even-parity checker" to Text3("Vérificateur de parité paire 4 bits","Comprobador de paridad par de 4 bits","Verificador de paridade par de 4 bits"),
        "Even=1 means the received four-bit word has even parity." to Text3("Pair=1 signifie que le mot reçu de quatre bits a une parité paire.","Par=1 significa que la palabra recibida de cuatro bits tiene paridad par.","Par=1 significa que a palavra recebida de quatro bits tem paridade par."),
        "Error=1 means an odd number of 1s was received; this detects, but cannot correct, an odd-bit error." to Text3("Erreur=1 signifie qu’un nombre impair de 1 a été reçu ; l’erreur est détectée, mais pas corrigée.","Error=1 significa que se recibió un número impar de 1; detecta, pero no corrige, errores de bits impares.","Erro=1 significa que foi recebida uma quantidade ímpar de 1; isso detecta, mas não corrige, erros de bits ímpares."),
        "BCD-to-seven-segment decoder" to Text3("Décodeur BCD vers afficheur sept segments","Decodificador BCD a siete segmentos","Decodificador BCD para sete segmentos"),
        "Digits 0–9 display their decimal glyph; invalid BCD inputs 10–15 turn every segment off." to Text3("Les chiffres 0–9 affichent leur forme décimale ; les entrées BCD invalides 10–15 éteignent tous les segments.","Los dígitos 0–9 muestran su forma decimal; las entradas BCD no válidas 10–15 apagan todos los segmentos.","Os dígitos 0–9 exibem sua forma decimal; entradas BCD inválidas de 10–15 apagam todos os segmentos."),
        "The model describes logic only; it does not model current limiting, display wiring or physical polarity." to Text3("Le modèle décrit uniquement la logique ; il ne simule ni limitation de courant, ni câblage d’afficheur, ni polarité physique.","El modelo solo describe la lógica; no simula limitación de corriente, cableado de pantalla ni polaridad física.","O modelo descreve apenas a lógica; não simula limitação de corrente, fiação do display ou polaridade física."),
        "SR latch · NOR" to Text3("Verrou SR · NOR","Latch SR · NOR","Latch SR · NOR"),
        "SR latch · NAND" to Text3("Verrou SR · NAND","Latch SR · NAND","Latch SR · NAND"),
        "D latch · enable" to Text3("Verrou D · validation","Latch D · habilitación","Latch D · habilitação"),
        "D flip-flop" to Text3("Bascule D","Flip-flop D","Flip-flop D"),
        "SR flip-flop" to Text3("Bascule SR","Flip-flop SR","Flip-flop SR"),
        "JK flip-flop" to Text3("Bascule JK","Flip-flop JK","Flip-flop JK"),
        "T flip-flop" to Text3("Bascule T","Flip-flop T","Flip-flop T"),
        "3-bit up counter" to Text3("Compteur ascendant 3 bits","Contador ascendente de 3 bits","Contador crescente de 3 bits"),
        "4-bit shift register" to Text3("Registre à décalage 4 bits","Registro de desplazamiento de 4 bits","Registrador de deslocamento de 4 bits"),
        "4-bit ring counter" to Text3("Compteur en anneau 4 bits","Contador en anillo de 4 bits","Contador em anel de 4 bits"),
        "4-bit Johnson counter" to Text3("Compteur Johnson 4 bits","Contador Johnson de 4 bits","Contador Johnson de 4 bits"),
        "10 set · 01 reset · 00 hold · 11 forbidden" to Text3("10 activation · 01 remise à zéro · 00 maintien · 11 interdit","10 set · 01 reset · 00 mantener · 11 prohibido","10 set · 01 reset · 00 manter · 11 proibido"),
        "Active-high, level-sensitive, cross-coupled NOR gates." to Text3("Portes NOR croisées, actives à 1 et sensibles au niveau.","Puertas NOR acopladas, activas en alto y sensibles al nivel.","Portas NOR cruzadas, ativas em nível alto e sensíveis ao nível."),
        "During S=R=1, both physical outputs are 0. Releasing to 00 leaves memory indeterminate until a valid set/reset." to Text3("Quand S=R=1, les deux sorties physiques valent 0. Le retour à 00 laisse la mémoire indéterminée jusqu’à un SET/RESET valide.","Con S=R=1, ambas salidas físicas son 0. Al volver a 00, la memoria queda indeterminada hasta un set/reset válido.","Com S=R=1, as duas saídas físicas são 0. Ao liberar para 00, a memória permanece indeterminada até um set/reset válido."),
        "01 set · 10 reset · 11 hold · 00 forbidden" to Text3("01 activation · 10 remise à zéro · 11 maintien · 00 interdit","01 set · 10 reset · 11 mantener · 00 prohibido","01 set · 10 reset · 11 manter · 00 proibido"),
        "Inputs nS/nR are active-low. A leading n means inversion." to Text3("Les entrées nS/nR sont actives à 0. Le préfixe n indique une inversion.","Las entradas nS/nR son activas en bajo. La n inicial indica inversión.","As entradas nS/nR são ativas em nível baixo. O n inicial indica inversão."),
        "During nS=nR=0 both physical outputs are 1; after release the stored state is indeterminate." to Text3("Quand nS=nR=0, les deux sorties physiques valent 1 ; après relâchement, l’état mémorisé est indéterminé.","Con nS=nR=0, ambas salidas físicas son 1; al liberar, el estado guardado es indeterminado.","Com nS=nR=0, as duas saídas físicas são 1; após soltar, o estado armazenado é indeterminado."),
        "EN=1: Q follows D · EN=0: hold" to Text3("EN=1 : Q suit D · EN=0 : maintien","EN=1: Q sigue a D · EN=0: mantener","EN=1: Q acompanha D · EN=0: manter"),
        "A transparent latch is NOT an edge-triggered flip-flop." to Text3("Un verrou transparent n’est PAS une bascule déclenchée sur front.","Un latch transparente NO es un flip-flop activado por flanco.","Um latch transparente NÃO é um flip-flop acionado por borda."),
        "While EN is high, changing D changes Q immediately. Lower EN to hold the last value." to Text3("Tant que EN vaut 1, Q suit immédiatement les changements de D. Mettez EN à 0 pour conserver la dernière valeur.","Mientras EN está alto, Q sigue los cambios de D al instante. Pon EN en bajo para mantener el último valor.","Enquanto EN está alto, Q acompanha D imediatamente. Coloque EN em baixo para manter o último valor."),
        "On ↑CLK: Q(next) = D" to Text3("Sur ↑CLK : Q(suivant) = D","En ↑CLK: Q(siguiente) = D","Na ↑CLK: Q(próximo) = D"),
        "A rising-edge flip-flop samples only a 0→1 clock edge." to Text3("Une bascule sur front montant échantillonne uniquement le front d’horloge 0→1.","Un flip-flop de flanco ascendente captura solo el flanco de reloj 0→1.","Um flip-flop de borda de subida captura apenas a borda de clock 0→1."),
        "Changing D while CLK remains high does not update Q. Falling edges do not capture D." to Text3("Modifier D lorsque CLK reste à 1 ne met pas Q à jour. Les fronts descendants n’échantillonnent pas D.","Cambiar D mientras CLK sigue alto no actualiza Q. Los flancos descendentes no capturan D.","Alterar D enquanto CLK permanece alto não atualiza Q. Bordas de descida não capturam D."),
        "On ↑CLK: set / reset / hold; 11 forbidden" to Text3("Sur ↑CLK : activation / remise à zéro / maintien ; 11 interdit","En ↑CLK: set / reset / mantener; 11 prohibido","Na ↑CLK: set / reset / manter; 11 proibido"),
        "The SR inputs are sampled on rising edges, not continuously." to Text3("Les entrées SR sont échantillonnées sur les fronts montants, pas en continu.","Las entradas SR se capturan en flancos ascendentes, no continuamente.","As entradas SR são capturadas nas bordas de subida, não continuamente."),
        "S=R=1 at a rising edge is forbidden; use a valid set/reset to recover." to Text3("S=R=1 sur un front montant est interdit ; utilisez un SET/RESET valide pour retrouver un état connu.","S=R=1 en un flanco ascendente está prohibido; usa un set/reset válido para recuperar.","S=R=1 na borda de subida é proibido; use um set/reset válido para recuperar."),
        "00 hold · 01 reset · 10 set · 11 toggle" to Text3("00 maintien · 01 remise à zéro · 10 activation · 11 bascule","00 mantener · 01 reset · 10 set · 11 alternar","00 manter · 01 reset · 10 set · 11 alternar"),
        "JK allows the 11 case: it toggles the stored bit." to Text3("JK autorise le cas 11 : le bit mémorisé bascule.","JK permite el caso 11: cambia el bit guardado.","JK permite o caso 11: alterna o bit armazenado."),
        "Q(next) = JQ′ + K′Q on a rising edge. This ideal edge model does not simulate race-around." to Text3("Sur front montant, Q(suivant) = JQ′ + K′Q. Ce modèle idéal ne simule pas le phénomène de race-around.","En flanco ascendente, Q(siguiente) = JQ′ + K′Q. Este modelo ideal no simula race-around.","Na borda de subida, Q(próximo) = JQ′ + K′Q. Este modelo ideal não simula race-around."),
        "On ↑CLK: T=0 hold · T=1 toggle" to Text3("Sur ↑CLK : T=0 maintien · T=1 bascule","En ↑CLK: T=0 mantener · T=1 alternar","Na ↑CLK: T=0 manter · T=1 alternar"),
        "Q(next) = T ⊕ Q on a rising edge." to Text3("Sur front montant, Q(suivant) = T ⊕ Q.","En flanco ascendente, Q(siguiente) = T ⊕ Q.","Na borda de subida, Q(próximo) = T ⊕ Q."),
        "Holding CLK high does not repeatedly toggle Q." to Text3("Maintenir CLK à 1 ne fait pas basculer Q en continu.","Mantener CLK alto no hace que Q cambie repetidamente.","Manter CLK alto não alterna Q repetidamente."),
        "On ↑CLK: RESET wins; EN counts mod 8" to Text3("Sur ↑CLK : RESET prioritaire ; EN compte modulo 8","En ↑CLK: RESET tiene prioridad; EN cuenta módulo 8","Na ↑CLK: RESET tem prioridade; EN conta módulo 8"),
        "Synchronous active-high RESET takes effect only at a rising edge." to Text3("Le RESET synchrone actif à 1 ne prend effet que sur un front montant.","RESET síncrono activo en alto solo actúa en un flanco ascendente.","RESET síncrono ativo em nível alto só atua na borda de subida."),
        "EN=0 holds the count. After 111 the count wraps to 000." to Text3("EN=0 conserve le compte. Après 111, il reboucle à 000.","EN=0 mantiene la cuenta. Después de 111, vuelve a 000.","EN=0 mantém a contagem. Após 111, ela volta para 000."),
        "On ↑CLK: RESET wins; EN shifts D into Q0" to Text3("Sur ↑CLK : RESET prioritaire ; EN décale D vers Q0","En ↑CLK: RESET tiene prioridad; EN desplaza D a Q0","Na ↑CLK: RESET tem prioridade; EN desloca D para Q0"),
        "Shift direction is toward Q3: Q3←Q2←Q1←Q0←D." to Text3("Le décalage se fait vers Q3 : Q3←Q2←Q1←Q0←D.","El desplazamiento va hacia Q3: Q3←Q2←Q1←Q0←D.","O deslocamento segue em direção a Q3: Q3←Q2←Q1←Q0←D."),
        "The earliest serial bit moves toward the MSB. RESET is synchronous, not asynchronous." to Text3("Le premier bit série se déplace vers le MSB. RESET est synchrone, pas asynchrone.","El primer bit serie avanza hacia el MSB. RESET es síncrono, no asíncrono.","O primeiro bit serial avança em direção ao MSB. RESET é síncrono, não assíncrono."),
        "On ↑CLK: rotate left · RESET loads 0001" to Text3("Sur ↑CLK : rotation à gauche · RESET charge 0001","En ↑CLK: rotación a la izquierda · RESET carga 0001","Na ↑CLK: rotação à esquerda · RESET carrega 0001"),
        "Starting from 0001: 0001 → 0010 → 0100 → 1000 → 0001." to Text3("En partant de 0001 : 0001 → 0010 → 0100 → 1000 → 0001.","Desde 0001: 0001 → 0010 → 0100 → 1000 → 0001.","Partindo de 0001: 0001 → 0010 → 0100 → 1000 → 0001."),
        "This demonstration starts and resets one-hot. A real all-zero ring cannot start without initialization." to Text3("Cette démonstration démarre et se réinitialise en one-hot. Un véritable compteur en anneau tout à zéro ne peut pas démarrer sans initialisation.","Esta demostración inicia y se reinicia en one-hot. Un contador real en anillo lleno de ceros no puede arrancar sin inicialización.","Esta demonstração inicia e redefine em one-hot. Um contador em anel real todo em zero não inicia sem inicialização."),
        "On ↑CLK: shift inverted Q3 into Q0" to Text3("Sur ↑CLK : décalage de l’inverse de Q3 vers Q0","En ↑CLK: desplazar Q3 invertido a Q0","Na ↑CLK: deslocar Q3 invertido para Q0"),
        "Starting from 0000: 0000 → 0001 → 0011 → 0111 → 1111 → 1110 → 1100 → 1000 → 0000." to Text3("En partant de 0000 : 0000 → 0001 → 0011 → 0111 → 1111 → 1110 → 1100 → 1000 → 0000.","Desde 0000: 0000 → 0001 → 0011 → 0111 → 1111 → 1110 → 1100 → 1000 → 0000.","Partindo de 0000: 0000 → 0001 → 0011 → 0111 → 1111 → 1110 → 1100 → 1000 → 0000."),
        "The four-bit twisted-ring counter has eight states in its initialized cycle. RESET is synchronous." to Text3("Le compteur Johnson sur quatre bits possède huit états dans son cycle initialisé. RESET est synchrone.","El contador Johnson de cuatro bits tiene ocho estados en el ciclo inicializado. RESET es síncrono.","O contador Johnson de quatro bits tem oito estados no ciclo inicializado. RESET é síncrono.")
    )
    fun translate(source:String,language:String):String? {
        val lang=language.lowercase()
        if(lang !in setOf("fr","es","pt"))return null
        entries[source]?.let { text -> return when(lang) {"fr"->text.fr;"es"->text.es;else->text.pt} }
        return translateOutputName(source,lang).takeIf{it!=source}
    }

    /** Human-readable circuit port labels; symbolic pins such as A, Q, and Cout stay unchanged. */
    fun translateOutputName(source:String,language:String):String {
        val labels=when(language.lowercase()) {
            "fr"->mapOf("Sum" to "Somme","Carry" to "Retenue","Diff" to "Différence","Borrow" to "Emprunt","Valid" to "Valide","Even" to "Pair","Error" to "Erreur")
            "es"->mapOf("Sum" to "Suma","Carry" to "Acarreo","Diff" to "Diferencia","Borrow" to "Préstamo","Valid" to "Válida","Even" to "Par","Error" to "Error")
            "pt"->mapOf("Sum" to "Soma","Carry" to "Transporte","Diff" to "Diferença","Borrow" to "Empréstimo","Valid" to "Válida","Even" to "Par","Error" to "Erro")
            else->return source
        }
        return labels[source]?:source
    }
}
